def _validate_name(name):
    """Validate beneficiary name."""
    if not name or not name.strip():
        return "Beneficiary name is required"
    if len(name) > 100:
        return "Name cannot exceed 100 characters"
    # Only letters, spaces, and periods allowed
    if not re.match(r'^[A-Za-z\s.]+$', name):
        return "Name can only contain letters, spaces and periods"
    return None


def _validate_account_number(account_number):
    """Validate account number."""
    if not re.match(r'^\d+$', account_number):
        return "Account number must contain only digits"
    if len(account_number) < 9:
        return "Account number must be between 9-18 digits"
    if len(account_number) > 18:
        return "Account number cannot exceed 18 digits"
    return None


def _validate_ifsc(ifsc):
    """Validate IFSC code."""
    if len(ifsc) != 11:
        return "Invalid IFSC code format. IFSC must be 11 characters"
    # Check if first 4 are uppercase letters
    if not re.match(r'^[A-Z]{4}[A-Z0-9]{7}$', ifsc):
        # Check if it's lowercase
        if re.match(r'^[a-z]{4}', ifsc):
            return "IFSC must be in uppercase"
        return "Invalid IFSC code format. IFSC must be 11 characters"
    return None


def _validate_account_type(account_type):
    """Validate account type."""
    if account_type not in ["Savings", "Current"]:
        return "Invalid account type"
    return None


