class API:
    """API-layer actions."""

    @staticmethod
    def add_beneficiary(name, account_number, ifsc, account_type):
        """Validates inputs and creates OTP session for adding beneficiary."""
        # Validate name
        error = _validate_name(name)
        if error:
            return {"ok": False, "error": error}

        # Validate account number
        error = _validate_account_number(account_number)
        if error:
            return {"ok": False, "error": error}

        # Validate IFSC
        error = _validate_ifsc(ifsc)
        if error:
            return {"ok": False, "error": error}

        # Validate account type
        error = _validate_account_type(account_type)
        if error:
            return {"ok": False, "error": error}

        # Check for duplicate
        for ben in DB.beneficiaries.values():
            if ben["account_number"] == account_number:
                return {"ok": False, "error": "Beneficiary with this account number already exists"}

        # Create OTP session
        beneficiary_id = DB.get_next_id()

        # Check if we should simulate expired OTP
        if _SESSION.get("simulate_expired_otp", False):
            created_time = datetime.now() - timedelta(minutes=CONFIG["otp_validity_minutes"] + 1)
            _SESSION["simulate_expired_otp"] = False
        else:
            created_time = datetime.now()

        DB.otp_sessions[beneficiary_id] = {
            "beneficiary_id": beneficiary_id,
            "otp": "123456",
            "operation": "add",
            "created_time": created_time,
            "attempts": 0,
            "data": {
                "name": name,
                "account_number": account_number,
                "ifsc": ifsc,
                "type": account_type
            }
        }

        return {"ok": True, "beneficiary_id": beneficiary_id, "otp": "123456"}

    @staticmethod
    def verify_otp(beneficiary_id, otp, operation):
        """Validates OTP for pending operation."""
        session = DB.otp_sessions.get(beneficiary_id)
        if not session:
            return {"ok": False, "error": "Invalid OTP session"}

        # Check if expired (simulated - we'll use a flag in the session)
        if hasattr(session.get("created_time"), "year"):
            elapsed = datetime.now() - session["created_time"]
            if elapsed > timedelta(minutes=CONFIG["otp_validity_minutes"]):
                return {"ok": False, "error": "OTP has expired. Please request a new OTP"}
        else:
            # For expired OTP test case - check if created_time is None or special marker
            if session.get("created_time") is None or session.get("expired", False):
                return {"ok": False, "error": "OTP has expired. Please request a new OTP"}

        # Check if max attempts exceeded first
        if session["attempts"] >= CONFIG["max_otp_attempts"]:
            return {"ok": False, "error": "Maximum OTP attempts exceeded. Please try after some time"}

        # Check OTP
        if session["otp"] != otp:
            session["attempts"] += 1
            # Check if max attempts reached after incrementing
            if session["attempts"] >= CONFIG["max_otp_attempts"]:
                return {"ok": False, "error": "Maximum OTP attempts exceeded. Please try after some time"}
            return {"ok": False, "error": "Invalid OTP. Please try again"}

        # OTP is correct - complete operation
        if operation == "add":
            data = session["data"]
            DB.beneficiaries[beneficiary_id] = {
                "id": beneficiary_id,
                "name": data["name"],
                "account_number": data["account_number"],
                "ifsc": data["ifsc"],
                "type": data["type"],
                "status": "Active",
                "added_date": datetime.now().strftime("%Y-%m-%d")
            }
        elif operation == "update":
            if beneficiary_id in DB.beneficiaries:
                DB.beneficiaries[beneficiary_id]["name"] = session["data"]["name"]
        elif operation == "delete":
            if beneficiary_id in DB.beneficiaries:
                del DB.beneficiaries[beneficiary_id]

        # Clear OTP session
        del DB.otp_sessions[beneficiary_id]

        return {"ok": True}

    @staticmethod
    def update_beneficiary(beneficiary_id, name):
        """Validates name and creates OTP session for updating beneficiary."""
        error = _validate_name(name)
        if error:
            return {"ok": False, "error": error}

        if beneficiary_id not in DB.beneficiaries:
            return {"ok": False, "error": "Beneficiary not found"}

        # Create OTP session
        DB.otp_sessions[beneficiary_id] = {
            "beneficiary_id": beneficiary_id,
            "otp": "654321",
            "operation": "update",
            "created_time": datetime.now(),
            "attempts": 0,
            "data": {"name": name}
        }

        return {"ok": True, "otp": "654321"}

    @staticmethod
    def delete_beneficiary(beneficiary_id):
        """Creates OTP session for deleting beneficiary."""
        if beneficiary_id not in DB.beneficiaries:
            return {"ok": False, "error": "Beneficiary not found"}

        # Create OTP session
        DB.otp_sessions[beneficiary_id] = {
            "beneficiary_id": beneficiary_id,
            "otp": "789012",
            "operation": "delete",
            "created_time": datetime.now(),
            "attempts": 0,
            "data": {}
        }

        return {"ok": True, "otp": "789012"}

    @staticmethod
    def resend_otp(beneficiary_id):
        """Generates new OTP for existing session."""
        session = DB.otp_sessions.get(beneficiary_id)
        if not session:
            return {"ok": False, "error": "No active OTP session"}

        session["otp"] = "999888"
        session["created_time"] = datetime.now()
        session["attempts"] = 0

        return {"ok": True, "otp": "999888"}

    @staticmethod
    def check_transaction_eligibility(beneficiary_id, amount):
        """Checks if beneficiary can receive transfer."""
        ben = DB.beneficiaries.get(beneficiary_id)
        if not ben:
            return {"ok": False, "error": "Beneficiary not found"}

        if ben["status"] == "Active":
            return {"ok": True, "eligible": True}
        elif ben["status"] == "Pending Approval":
            return {"ok": True, "eligible": False, "reason": "Cannot transfer to unapproved beneficiary. Please wait for approval"}

        return {"ok": True, "eligible": False, "reason": "Beneficiary not eligible"}

    @staticmethod
    def get_beneficiaries():
        """Returns list of all beneficiaries for logged-in user."""
        beneficiaries = []
        for ben in DB.beneficiaries.values():
            beneficiaries.append({
                "id": ben["id"],
