def test_expired_otp():
    """Test that expired OTP is rejected."""
    setup()

    # Login
    UI.login("testuser@bank.test", "Test@1234")

    # Navigate to Add Beneficiary
    UI.click_button("Add Beneficiary")

    # Fill in beneficiary details
    UI.fill_field("beneficiary_name", "Meera Joshi")
    UI.fill_field("account_number", "7788990011223344")
    UI.fill_field("ifsc_code", "KOTA0001234")
    UI.fill_field("account_type", "Savings")

    # Set flag to simulate expired OTP
    _SESSION["simulate_expired_otp"] = True

    # Submit to create OTP session (will be created as expired)
    UI.click_button("Submit")

    # Try to verify with correct OTP
    UI.fill_field("otp", "123456")
    result = UI.click_button("Verify")

    # Verify the results
    assert result == False, f"Expected False, got {result}"
    assert UI.visible_message() == "OTP has expired. Please request a new OTP", f"Wrong message: {UI.visible_message()}"
    assert Database.db_get_beneficiary_by_account("7788990011223344") is None, "Beneficiary should not be added"

    print("✓ test_expired_otp passed")


